            swap(&m, &n)
        }

        var res = 1
        var j = 1
        for i in m..<(m + n - 1) {
            res *= i
            res /= j
            j += 1
        }

        return res
    }
}

impl Solution {
    pub fn unique_paths(m: i32, n: i32) -> i32 {
        if m == 1 || n == 1 {
            return 1;
        }
        let (mut m, mut n) = (m as i64, n as i64);
        if m < n {
            std::mem::swap(&mut m, &mut n);
        }

        let mut res: i64 = 1;
        let mut j: i64 = 1;
        for i in m..(m + n - 1) {
            res *= i;
            res /= j;
            j += 1;
        }

        res as i32
    }
}
